public class Solution {
    public static void moveZeroes(int[] arr) {
        int insertPos = 0;
        for (int num : arr) {
            if (num != 0) {
                arr[insertPos++] = num;
            }
        }
        while (insertPos < arr.length) {
            arr[insertPos++] = 0;
        }
    }

    public static void main(String[] args) {
        int[] data = {0, 1, 0, 3, 12};
        moveZeroes(data);
        System.out.println("Zeroes moved to end: " + Arrays.toString(data));
    }
}

public class Solution {
    public static int[][] transpose(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] result = new int[cols][rows];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                result[c][r] = matrix[r][c];
            }
        }
        return result;
    }

    public static void main(String[] args) {
        int[][] original = {
            {1, 2, 3},
            {4, 5, 6}
        };
        int[][] transposed = transpose(original);
        System.out.println("Transposed Matrix (3x2):");
        for (int[] row : transposed) {
            System.out.println(row[0] + " " + row[1]);
        }
    }
}

public class Solution {
    public static int findMissingNumber(int[] arr, int n) {
        int xorAll = 0;
        for (int i = 1; i <= n; i++) {
            xorAll ^= i;
        }
        for (int num : arr) {
            xorAll ^= num;
        }
        return xorAll;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 4, 5, 6}; // Missing 3 from 1..6
        int missing = findMissingNumber(numbers, 6);
        System.out.println("Missing number: " + missing);
    }
}

